fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }

fn rewrite_voxel(packed: u32, new_mat: u32, new_thermal: u32, new_phase: u32) -> u32 {
    let keep = packed & 0xF0FF0000u;
    return (new_mat & MATERIAL_MASK)
         | ((new_thermal & THERMAL_MASK) << THERMAL_SHIFT)
         | keep
         | ((new_phase & PHASE_MASK) << PHASE_SHIFT);
}

// Fused function: count air neighbors AND find first burning neighbor
// Returns: (air_count | (burning_dir << 16) | (fuel_energy << 24))
fn scan_neighbors(x: u32, y: u32) -> u32 {
    var air_count = 0u;
    var burning_info = 0u;  // (dir << 16) | (fuel_energy << 24)

    // Precompute bounds
    let bounds = vec4<u32>(
        u32(x > 0u),
        u32(x < GRID_WIDTH - 1u), 
        u32(y > 0u),
        u32(y < GRID_HEIGHT - 1u)
    );

    // Check order based on parity for determinism
    let parity = (x + y) & 1u;
    let order = select(
        vec4<u32>(0u, 1u, 2u, 3u),  // left, right, up, down
        vec4<u32>(2u, 3u, 0u, 1u),  // up, down, left, right
        parity == 1u
    );

    for (var i = 0u; i < 4u; i++) {
        let dir = order[i];
        if (bounds[dir] == 0u) { continue; }

        // Compute neighbor position
        let nx = x + select(select(0u, 1u, dir == 1u), u32(-1i32), dir == 0u);
        let ny = y + select(select(0u, 1u, dir == 3u), u32(-1i32), dir == 2u);

        let n = grid_in[get_idx(nx, ny)];
        let n_mat = get_material(n);

        if (n_mat == MAT_AIR) {
            air_count += 1u;
        } else if (burning_info == 0u) {  // Only check for burning if we haven't found one yet
