            let n_fuel = ct(n_mat, 16u);

            if (n_fuel > 0u && n_thermal > n_flash) {
                // Found burning neighbor - encode direction and fuel energy
                burning_info = ((dir + 1u) << 16u) | (n_fuel << 24u);
