    // Vectorized bounds check
    let bounds = vec4<u32>(u32(x > 0u), u32(x < GRID_WIDTH - 1u), u32(y > 0u), u32(y < GRID_HEIGHT - 1u));

    // Check each direction only if in bounds
    if (bounds.x != 0u && get_material(grid_in[get_idx(x - 1u, y)]) == MAT_AIR) { return true; }
    if (bounds.y != 0u && get_material(grid_in[get_idx(x + 1u, y)]) == MAT_AIR) { return true; }
